-- ES/DE/FR translations for the rest of Croatia's deep-dive content,
-- including the lifecycle/pill card ('The three parallel processes')
-- and penalty-row translations (Companies/Individuals combined into
-- fine_amount, matching the English migration's approach).

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Dual — intercambio descentralizado + reporte en tiempo real', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Las especificaciones técnicas de HR-FISK, los detalles operativos del AMS y los regímenes de sanciones continúan evolucionando — confirme los requisitos actuales directamente con la Administración Tributaria croata antes de construir una integración.', 'La reforma Fiskalizacija 2.0 de Croacia añade un mandato B2B completo y un régimen de fiscalización B2C ampliado sobre un sistema B2G que lleva años funcionando.', 'Croacia se basa en el modelo de factura europeo estándar, pero añade una capa claramente nacional de campos obligatorios adicionales.', 'Esta es la parte que sorprende a la gente: Croacia no es un único flujo, son tres que funcionan en paralelo — intercambio, fiscalización y reporte mensual electrónico.', 'Dado que Croacia gestiona tres obligaciones paralelas, "cumplir" significa configurar las tres — no solo elegir un Punto de Acceso.', 'Croacia no se concede ningún "período de gracia" — el régimen de sanciones se aplica desde la fecha de entrada en vigor de cada elemento, con rangos escalados según el tamaño de la empresa.' FROM countries WHERE name_en = 'Croatia';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Dual — dezentraler Austausch + Echtzeitmeldung', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die technischen HR-FISK-Spezifikationen, die operativen AMS-Details und die Bußgeldregelungen entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt bei der kroatischen Steuerverwaltung, bevor Sie eine Integration aufbauen.', 'Kroatiens Fiskalizacija-2.0-Reform legt eine vollständige B2B-Pflicht und ein erweitertes B2C-Fiskalisierungsregime auf ein B2G-System, das bereits seit Jahren läuft.', 'Kroatien baut auf dem europäischen Standardrechnungsmodell auf, fügt jedoch eine deutlich nationale Ebene zusätzlicher Pflichtfelder hinzu.', 'Das ist der Teil, der viele überrascht: Kroatien besteht nicht aus einem Ablauf, sondern aus drei parallel laufenden — Austausch, Fiskalisierung und monatliches E-Reporting.', 'Da Kroatien drei parallele Pflichten führt, bedeutet "konform werden", alle drei einzurichten — nicht nur einen Access Point auszuwählen.', 'Kroatien gewährt sich keine "Bußgeld-Schonfrist" — der Bußgeldkatalog gilt ab dem Starttermin jedes einzelnen Elements, mit nach Unternehmensgröße gestaffelten Spannen.' FROM countries WHERE name_en = 'Croatia';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Double — échange décentralisé + déclaration en temps réel', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les spécifications techniques HR-FISK, les détails opérationnels de l''AMS et les barèmes de sanctions continuent d''évoluer — confirmez les exigences actuelles directement auprès de l''administration fiscale croate avant de construire une intégration.', 'La réforme Fiskalizacija 2.0 de la Croatie superpose une obligation B2B complète et un régime de fiscalisation B2C étendu à un système B2G en fonctionnement depuis des années.', 'La Croatie s''appuie sur le modèle de facture européen standard, mais y ajoute une couche nettement nationale de champs obligatoires supplémentaires.', 'C''est l''aspect qui surprend le plus : la Croatie ne compte pas un seul flux, mais trois fonctionnant en parallèle — échange, fiscalisation et déclaration électronique mensuelle.', 'Comme la Croatie fait fonctionner trois obligations en parallèle, « se mettre en conformité » signifie configurer les trois — pas seulement choisir un Access Point.', 'La Croatie ne s''accorde aucune « période de grâce » — le barème de sanctions s''applique dès la date d''entrée en vigueur de chaque élément, avec des fourchettes échelonnées selon la taille de l''entreprise.' FROM countries WHERE name_en = 'Croatia';

