INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Sintaxis y estándar', '[["Sintaxis base", "XML UBL 2.1"], ["Alineación europea", "EN 16931-1:2017"], ["CIUS nacional", "HR-FISK 2.0"], ["Compatibilidad con Peppol", "Admite Peppol BIS 3.0 como formato común"]]', 'HR-FISK 2.0 va más allá de la base de EN 16931 — las extensiones de Croacia no son cosméticas, añaden campos que el estándar europeo no exige.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'file_format' AND dct.title = 'Syntax & standard';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Syntax & Standard', '[["Basissyntax", "UBL 2.1 XML"], ["Europäische Ausrichtung", "EN 16931-1:2017"], ["Nationale CIUS", "HR-FISK 2.0"], ["Peppol-Kompatibilität", "Unterstützt Peppol BIS 3.0 als gemeinsames Format"]]', 'HR-FISK 2.0 geht über die EN-16931-Basis hinaus — Kroatiens Erweiterungen sind nicht kosmetischer Natur, sie fügen Felder hinzu, die der europäische Standard nicht verlangt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'file_format' AND dct.title = 'Syntax & standard';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Syntaxe et norme', '[["Syntaxe de base", "XML UBL 2.1"], ["Alignement européen", "EN 16931-1:2017"], ["CIUS nationale", "HR-FISK 2.0"], ["Compatibilité Peppol", "Prend en charge Peppol BIS 3.0 comme format commun"]]', 'HR-FISK 2.0 va au-delà de la base EN 16931 — les extensions croates ne sont pas cosmétiques, elles ajoutent des champs que la norme européenne n''exige pas.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'file_format' AND dct.title = 'Syntax & standard';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Campos obligatorios adicionales', '[["Identificadores", "OIB del vendedor y del comprador (número fiscal croata)"], ["Clasificación de producto", "Código de producto CPA de 6 dígitos"], ["Detalle de pago", "Datos de la cuenta bancaria"]]', 'Estas tres adiciones — OIB, código CPA y datos bancarios — son exactamente los campos que hacen tropezar a los ERP configurados para una implementación genérica de EN 16931 en lugar de específicamente para Croacia.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'file_format' AND dct.title = 'Extra mandatory fields';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Zusätzliche Pflichtfelder', '[["Kennungen", "OIB des Verkäufers & Käufers (kroatische Steuernummer)"], ["Produktklassifizierung", "6-stelliger CPA-Produktcode"], ["Zahlungsdetails", "Bankverbindung"]]', 'Diese drei Ergänzungen — OIB, CPA-Code und Bankdaten — sind genau die Felder, an denen ERP-Systeme scheitern, die für eine generische EN-16931-Implementierung statt speziell für Kroatien konfiguriert sind.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'file_format' AND dct.title = 'Extra mandatory fields';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Champs obligatoires supplémentaires', '[["Identifiants", "OIB du vendeur et de l''acheteur (numéro fiscal croate)"], ["Classification produit", "Code produit CPA à 6 chiffres"], ["Détail de paiement", "Coordonnées bancaires"]]', 'Ces trois ajouts — OIB, code CPA et coordonnées bancaires — sont exactement les champs qui font trébucher les ERP configurés pour une implémentation EN 16931 générique plutôt que spécifiquement pour la Croatie.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'file_format' AND dct.title = 'Extra mandatory fields';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Firmas', '[["Envoltura SOAP", "Siempre firmada con un certificado cualificado"], ["El propio XML de la factura", "Firma opcional, pero práctica habitual"]]', 'No asuma que el XML de la factura necesita su propia firma como en el caso de FatturaPA en Italia — el requisito de Croacia se sitúa en la capa de transporte (SOAP).', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'file_format' AND dct.title = 'Signatures';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Signaturen', '[["SOAP-Umschlag", "Immer mit qualifiziertem Zertifikat signiert"], ["Die Rechnungs-XML selbst", "Signatur optional, aber gängige Praxis"]]', 'Gehen Sie nicht davon aus, dass die Rechnungs-XML wie bei Italiens FatturaPA eine eigene Signatur benötigt — Kroatiens Anforderung liegt stattdessen auf der Transportebene (SOAP).', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'file_format' AND dct.title = 'Signatures';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Signatures', '[["Enveloppe SOAP", "Toujours signée avec un certificat qualifié"], ["Le XML de la facture lui-même", "Signature facultative, mais pratique courante"]]', 'Ne présumez pas que le XML de la facture a besoin de sa propre signature comme pour la FatturaPA italienne — l''exigence croate se situe au niveau de la couche de transport (SOAP).', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'file_format' AND dct.title = 'Signatures';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Excepciones', '[["Facturas en papel", "Permitidas solo en casos nacionales limitados"], ["Motivo habitual", "El destinatario no está registrado en el directorio AMS"]]', 'Se trata de una vía de escape limitada, no de una exención general — existe específicamente para el caso en que el sistema realmente no pueda encontrar una dirección enrutable para el destinatario.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'file_format' AND dct.title = 'Exceptions';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Ausnahmen', '[["Papierrechnungen", "Nur in begrenzten inländischen Fällen zulässig"], ["Häufiger Auslöser", "Empfänger nicht im AMS-Verzeichnis registriert"]]', 'Dies ist ein enges Schlupfloch, kein allgemeiner Opt-out — es besteht speziell für den Fall, dass das System tatsächlich keine routbare Adresse für den Empfänger findet.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'file_format' AND dct.title = 'Exceptions';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Exceptions', '[["Factures papier", "Autorisées uniquement dans des cas nationaux limités"], ["Déclencheur courant", "Destinataire non enregistré dans l''annuaire AMS"]]', 'Il s''agit d''une échappatoire étroite, pas d''une dérogation générale — elle existe spécifiquement pour le cas où le système ne parvient réellement pas à trouver une adresse routable pour le destinataire.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'file_format' AND dct.title = 'Exceptions';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Intercambio de facturas (AS4)', '[["Envoltura", "Protocolo AS4 con TLS mutuo"], ["Descubrimiento", "AMS → MPS del comprador → punto de acceso del comprador + clave pública"], ["Modelo de enrutamiento", "Dinámico, similar a Peppol pero gestionado localmente"]]', 'El Punto de Acceso del proveedor consulta el AMS, que devuelve la URL del Servicio de Metadatos del comprador (MPS); el PA consulta después ese MPS para descubrir el punto técnico del PA del comprador. No se necesitan conexiones bilaterales estáticas.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'scope_transmission' AND dct.title = 'Invoice exchange (AS4)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Rechnungsaustausch (AS4)', '[["Umschlag", "AS4-Protokoll mit gegenseitigem TLS"], ["Erkennung", "AMS → MPS des Käufers → AP-Endpunkt des Käufers + öffentlicher Schlüssel"], ["Routing-Modell", "Dynamisch, Peppol-ähnlich, aber lokal verwaltet"]]', 'Der Access Point des Lieferanten fragt das AMS ab, das die URL des Metadata Service (MPS) des Käufers zurückgibt; der AP fragt dann diesen MPS ab, um den technischen Endpunkt des Käufer-AP zu ermitteln. Keine statischen bilateralen Verbindungen erforderlich.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'scope_transmission' AND dct.title = 'Invoice exchange (AS4)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Échange de factures (AS4)', '[["Enveloppe", "Protocole AS4 avec TLS mutuel"], ["Découverte", "AMS → MPS de l''acheteur → point de terminaison AP de l''acheteur + clé publique"], ["Modèle de routage", "Dynamique, à la façon de Peppol mais géré localement"]]', 'L''Access Point du fournisseur interroge l''AMS, qui renvoie l''URL du service de métadonnées (MPS) de l''acheteur ; l''AP interroge ensuite ce MPS pour découvrir le point de terminaison technique de l''AP de l''acheteur. Aucune connexion bilatérale statique n''est nécessaire.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'scope_transmission' AND dct.title = 'Invoice exchange (AS4)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Reporte de fiscalización', '[["Lado emisor", "En tiempo real, en el momento de la emisión"], ["Lado receptor", "En tiempo real, al recibirla (dentro de 5 días)"]]', 'Ambas partes de una transacción confirman de forma independiente a la Administración Tributaria — esto es lo que convierte la fiscalización en un control genuino de dos lados y no en una única presentación.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'scope_transmission' AND dct.title = 'Fiscalisation reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Fiskalisierungsmeldung', '[["Ausstellerseite", "In Echtzeit, bei Ausstellung"], ["Empfängerseite", "In Echtzeit, bei Erhalt (innerhalb von 5 Tagen)"]]', 'Beide Seiten einer Transaktion bestätigen sie unabhängig voneinander gegenüber der Steuerverwaltung — das macht die Fiskalisierung zu einer echten zweiseitigen Kontrolle statt einer einseitigen Meldung.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'scope_transmission' AND dct.title = 'Fiscalisation reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Déclaration de fiscalisation', '[["Côté émetteur", "En temps réel, à l''émission"], ["Côté destinataire", "En temps réel, à la réception (dans un délai de 5 jours)"]]', 'Les deux parties d''une transaction la confirment indépendamment à l''administration fiscale — c''est ce qui fait de la fiscalisation un contrôle véritablement bilatéral plutôt qu''une déclaration à sens unique.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'scope_transmission' AND dct.title = 'Fiscalisation reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Reporte electrónico mensual', '[["Plazo", "Día 20 del mes siguiente"], ["Los receptores reportan", "Facturas rechazadas y no entregadas"], ["Los emisores reportan", "Pagos recibidos"]]', 'Esta tercera capa detecta lo que los flujos en tiempo real pasan por alto — concretamente, qué sucedió con una factura tras su emisión (¿rechazada? ¿pagada?) y no solo confirmar que existió.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'scope_transmission' AND dct.title = 'Monthly e-reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Monatliches E-Reporting', '[["Frist", "20. des Folgemonats"], ["Empfänger melden", "Abgelehnte und nicht zugestellte Rechnungen"], ["Aussteller melden", "Erhaltene Zahlungen"]]', 'Diese dritte Ebene erfasst, was die Echtzeitabläufe übersehen — konkret, was nach der Ausstellung mit einer Rechnung geschah (abgelehnt? bezahlt?), statt nur ihre Existenz zu bestätigen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'scope_transmission' AND dct.title = 'Monthly e-reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Déclaration électronique mensuelle', '[["Échéance", "Le 20 du mois suivant"], ["Les destinataires déclarent", "Les factures rejetées et non livrées"], ["Les émetteurs déclarent", "Les paiements reçus"]]', 'Cette troisième couche capte ce que les flux en temps réel manquent — précisément, ce qui est arrivé à une facture après son émission (rejetée ? payée ?), plutôt que de simplement confirmer son existence.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'scope_transmission' AND dct.title = 'Monthly e-reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Puntos de acceso y el AMS', '[["AMS", "Directorio de direcciones gestionado por el gobierno central"], ["Un PA por identificador", "p. ej., un OIB se asigna a un único Punto de Acceso receptor"], ["Múltiples identificadores", "Identificadores distintos (p. ej. GLN) pueden enrutarse a PA diferentes"], ["Requisitos del PA", "Certificado por conformidad, cumple ISO 27001 + RGPD"]]', 'Las grandes empresas tienen la opción de integrar su ERP directamente con la Administración Tributaria en lugar de pasar por un Punto de Acceso externo — vale la pena evaluarlo si su volumen de facturas justifica el desarrollo.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'scope_transmission' AND dct.title = 'Access points & the AMS';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Access Points & das AMS', '[["AMS", "Zentral von der Regierung geführtes Adressverzeichnis"], ["Ein AP pro Kennung", "z. B. wird eine OIB einem einzigen empfangenden Access Point zugeordnet"], ["Mehrere Kennungen", "Verschiedene Kennungen (z. B. GLN) können zu unterschiedlichen APs geroutet werden"], ["AP-Anforderungen", "Konformitätsgeprüft, ISO-27001- + DSGVO-konform"]]', 'Große Unternehmen haben die Möglichkeit, ihr ERP direkt mit der Steuerverwaltung zu integrieren, statt über einen externen Access Point zu gehen — lohnt sich zu prüfen, wenn Ihr Rechnungsvolumen den Aufwand rechtfertigt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'scope_transmission' AND dct.title = 'Access points & the AMS';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Points d''accès et l''AMS', '[["AMS", "Annuaire d''adresses géré par le gouvernement central"], ["Un AP par identifiant", "p. ex. un OIB est associé à un seul Access Point récepteur"], ["Identifiants multiples", "Des identifiants différents (p. ex. GLN) peuvent être routés vers des AP différents"], ["Exigences AP", "Testé pour la conformité, conforme ISO 27001 + RGPD"]]', 'Les grandes entreprises ont la possibilité d''intégrer leur ERP directement à l''administration fiscale plutôt que de passer par un Access Point tiers — à évaluer si vos volumes de factures justifient ce développement.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'scope_transmission' AND dct.title = 'Access points & the AMS';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚠️ Casos graves/reiterados', NULL, NULL, 'Algunas fuentes citan sanciones que alcanzan hasta 500.000 € para incumplimientos graves o reiterados en el reporte en tiempo real — considere los rangos anteriores como el régimen estándar, con posibilidad de escalada para casos flagrantes o reiterados.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'penalties_related' AND dct.title = '⚠️ Severe/repeated cases';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚠️ Schwere/wiederholte Fälle', NULL, NULL, 'Einige Quellen nennen Bußgelder von bis zu 500.000 € für schwere oder wiederholte Verstöße bei der Echtzeitmeldung — betrachten Sie die obigen Spannen als Standardkatalog, mit möglicher Eskalation bei gravierenden oder wiederholten Verstößen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'penalties_related' AND dct.title = '⚠️ Severe/repeated cases';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚠️ Cas graves/répétés', NULL, NULL, 'Certaines sources font état de sanctions atteignant jusqu''à 500 000 € pour des manquements graves ou répétés à la déclaration en temps réel — considérez les fourchettes ci-dessus comme le barème standard, avec une possibilité d''escalade en cas de non-conformité flagrante ou répétée.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'penalties_related' AND dct.title = '⚠️ Severe/repeated cases';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🚫 Sin período de gracia', NULL, NULL, 'A diferencia de Bélgica, Polonia o Francia, Croacia no ha anunciado un período de gracia para su entrada en vigor en 2026 — el cumplimiento desde el primer día es lo esperado, no un objetivo flexible.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'penalties_related' AND dct.title = '🚫 No penalty holiday';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🚫 Keine Bußgeld-Schonfrist', NULL, NULL, 'Anders als Belgien, Polen oder Frankreich hat Kroatien für seinen Start 2026 keine Übergangsfrist angekündigt — Konformität ab dem ersten Tag ist die Erwartung, kein weiches Ziel.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'penalties_related' AND dct.title = '🚫 No penalty holiday';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🚫 Aucune période de grâce', NULL, NULL, 'Contrairement à la Belgique, la Pologne ou la France, la Croatie n''a annoncé aucune période de grâce pour son entrée en vigueur en 2026 — la conformité dès le premier jour est attendue, pas un objectif souple.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'penalties_related' AND dct.title = '🚫 No penalty holiday';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📋 Más allá de las multas', NULL, NULL, 'El incumplimiento también implica riesgo de disputas de facturas, pagos retrasados, trabajo adicional de auditoría y conciliación y — en el caso de manipulación de software — el posible cierre del establecimiento.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'penalties_related' AND dct.title = '📋 Beyond fines';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📋 Über Bußgelder hinaus', NULL, NULL, 'Nichteinhaltung birgt auch das Risiko von Rechnungsstreitigkeiten, verzögerten Zahlungen, zusätzlichem Prüf- und Abstimmungsaufwand und — im Fall von Softwaremanipulation — der möglichen Schließung von Geschäftsräumen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'penalties_related' AND dct.title = '📋 Beyond fines';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📋 Au-delà des amendes', NULL, NULL, 'La non-conformité expose également à des litiges de facturation, des paiements retardés, un travail supplémentaire d''audit et de rapprochement, et — en cas de manipulation du logiciel — une éventuelle fermeture des locaux commerciaux.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Croatia' AND dc.section = 'penalties_related' AND dct.title = '📋 Beyond fines';

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'es', 'Los tres procesos paralelos', 'A diferencia de un único flujo de compensación, Croacia exige que los tres funcionen de forma independiente:', 'Esta estructura de "doble reporte" crea un ciclo de auditoría cerrado — la autoridad fiscal recibe confirmaciones independientes tanto del lado vendedor como del comprador, no solo un único flujo.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Croatia';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'de', 'Die drei parallelen Prozesse', 'Anders als bei einem einzigen Clearing-Ablauf verlangt Kroatien, dass alle drei unabhängig voneinander laufen:', 'Diese "doppelte Meldestruktur" schafft eine geschlossene Prüfschleife — die Steuerbehörde erhält unabhängige Bestätigungen sowohl von der Verkäufer- als auch von der Käuferseite, nicht nur einen einzelnen Feed.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Croatia';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'fr', 'Les trois processus parallèles', 'Contrairement à un flux de contrôle unique, la Croatie exige que les trois fonctionnent de manière indépendante :', 'Cette structure de « double déclaration » crée une boucle d''audit fermée — l''administration fiscale reçoit des confirmations indépendantes à la fois du côté vendeur et du côté acheteur, pas un flux unique.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Croatia';

