INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Identifique sus identificadores', 'Determine qué identificadores utiliza su empresa para enrutar facturas — como mínimo su OIB, además de cualquier identificador secundario como el GLN — ya que cada uno puede asignarse a un Punto de Acceso receptor distinto en el AMS.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Map your identifiers';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Ermitteln Sie Ihre Kennungen', 'Klären Sie, welche Kennungen Ihr Unternehmen zur Weiterleitung von Rechnungen verwendet — mindestens Ihre OIB, plus etwaige sekundäre Kennungen wie GLN — da jede einem anderen empfangenden Access Point im AMS zugeordnet sein kann.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Map your identifiers';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Recensez vos identifiants', 'Déterminez quels identifiants votre entreprise utilise pour l''acheminement des factures — au minimum votre OIB, ainsi que tout identifiant secondaire comme le GLN — car chacun peut être associé à un Access Point récepteur différent dans l''AMS.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Map your identifiers';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija un Intermediario de Información o Punto de Acceso acreditado', 'Confirme que el proveedor elegido figura en la lista oficial de intermediarios certificados de la Administración Tributaria croata, con evaluaciones de conformidad y seguridad superadas — o evalúe la integración directa del ERP si presenta grandes volúmenes.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Choose an accredited Information Intermediary or Access Point';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie einen akkreditierten Informationsvermittler oder Access Point', 'Bestätigen Sie, dass Ihr gewählter Anbieter auf der offiziellen Liste zertifizierter Vermittler der kroatischen Steuerverwaltung steht, mit bestandenen Konformitäts- und Sicherheitsprüfungen — oder prüfen Sie eine direkte ERP-Integration, wenn Sie ein Großvolumen-Einreicher sind.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Choose an accredited Information Intermediary or Access Point';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez un intermédiaire d''information ou un Access Point accrédité', 'Vérifiez que le prestataire choisi figure sur la liste officielle des intermédiaires certifiés de l''administration fiscale croate, ayant passé les évaluations de conformité et de sécurité — ou envisagez une intégration ERP directe si vous traitez de gros volumes.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Choose an accredited Information Intermediary or Access Point';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Registre su Punto de Acceso receptor en el AMS', 'Hágalo por cada identificador — no asuma que registrar su OIB cubre automáticamente los identificadores secundarios que también utilice.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Register your receiving Access Point in the AMS';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Registrieren Sie Ihren empfangenden Access Point im AMS', 'Tun Sie dies pro Kennung — gehen Sie nicht davon aus, dass die Registrierung Ihrer OIB automatisch alle sekundären Kennungen abdeckt, die Sie ebenfalls verwenden.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Register your receiving Access Point in the AMS';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Enregistrez votre Access Point récepteur dans l''AMS', 'Faites-le pour chaque identifiant — ne présumez pas que l''enregistrement de votre OIB couvre automatiquement les identifiants secondaires que vous utilisez également.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Register your receiving Access Point in the AMS';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Valide su software de facturación frente a HR-FISK 2.0', 'Confirme que la generación de UBL 2.1 incluye los campos específicos de Croacia — OIB, códigos de producto CPA de 6 dígitos y datos de cuenta bancaria — y no solo el conjunto base de EN 16931.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Validate your invoicing software against HR-FISK 2.0';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Validieren Sie Ihre Rechnungssoftware gegen HR-FISK 2.0', 'Bestätigen Sie, dass die UBL-2.1-Erzeugung die kroatienspezifischen Felder enthält — OIB, 6-stellige CPA-Produktcodes und Bankverbindung — nicht nur den EN-16931-Basissatz.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Validate your invoicing software against HR-FISK 2.0';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Validez votre logiciel de facturation par rapport à HR-FISK 2.0', 'Vérifiez que la génération UBL 2.1 inclut les champs spécifiques à la Croatie — OIB, codes produit CPA à 6 chiffres et coordonnées bancaires — pas seulement l''ensemble de base EN 16931.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Validate your invoicing software against HR-FISK 2.0';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure ambos flujos de fiscalización', 'Configure el reporte en tiempo real a la Administración Tributaria para las facturas que emite, y un proceso independiente de confirmación en tiempo real para las facturas que recibe — son genuinamente dos flujos técnicos distintos, no uno.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Build both fiscalisation flows';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie beide Fiskalisierungsabläufe ein', 'Richten Sie die Echtzeitmeldung an die Steuerverwaltung für von Ihnen ausgestellte Rechnungen ein sowie einen separaten Echtzeit-Bestätigungsprozess für empfangene Rechnungen — dies sind tatsächlich zwei unterschiedliche technische Abläufe, nicht einer.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Build both fiscalisation flows';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place les deux flux de fiscalisation', 'Configurez la déclaration en temps réel à l''administration fiscale pour les factures que vous émettez, ainsi qu''un processus de confirmation en temps réel distinct pour les factures que vous recevez — ce sont réellement deux flux techniques différents, pas un seul.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Build both fiscalisation flows';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure el ciclo mensual de reporte electrónico', 'Cree un proceso para reportar las facturas rechazadas/no entregadas (como receptor) y los pagos recibidos (como emisor) antes del plazo del día 20 de cada mes, sin excepción.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Set up the monthly e-reporting cycle';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie den monatlichen E-Reporting-Zyklus ein', 'Bauen Sie einen Prozess auf, um abgelehnte/nicht zugestellte Rechnungen (als Empfänger) und erhaltene Zahlungen (als Aussteller) vor der Frist am 20. jeden Monat ausnahmslos zu melden.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Set up the monthly e-reporting cycle';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place le cycle de déclaration électronique mensuel', 'Mettez en place un processus pour déclarer les factures rejetées/non livrées (en tant que destinataire) et les paiements reçus (en tant qu''émetteur) avant l''échéance du 20 de chaque mois, sans exception.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Croatia' AND dst.title = 'Set up the monthly e-reporting cycle';

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Porezna uprava (Administración Tributaria croata)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Croatia';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'Porezna uprava (Kroatische Steuerverwaltung)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Croatia';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Porezna uprava (Administration fiscale croate)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Croatia';
